// Service worker. File list + version come from abc/manifest.js (generated by `node tools/check.js --fix`),
// so new languages / modules are cached for offline use without editing this file.
importScripts('abc/manifest.js');
const CACHE = 'toddler-' + self.MANIFEST.version;

self.addEventListener('install', e => {
  // relative to the SW scope → works on GitHub Pages (/toddler-games/) and on localhost
  e.waitUntil(caches.open(CACHE).then(c => c.addAll(self.MANIFEST.files.map(f => new Request(f, { cache: 'reload' })))));
  self.skipWaiting();
});

self.addEventListener('activate', e => {
  e.waitUntil(caches.keys().then(keys => Promise.all(keys.filter(k => k.startsWith('toddler-') && k !== CACHE).map(k => caches.delete(k)))));
  self.clients.claim();
});

// Network-first (fresh deploys show on next load), cache fallback offline. Only good responses are stored.
self.addEventListener('fetch', e => {
  if (e.request.method !== 'GET' || new URL(e.request.url).origin !== location.origin) return;
  e.respondWith(
    fetch(e.request, { cache: 'no-cache' })
      .then(r => {
        if (r.ok) { const clone = r.clone(); caches.open(CACHE).then(c => c.put(e.request, clone)); }
        return r;
      })
      .catch(() => caches.match(e.request, { ignoreSearch: true }))
  );
});
